import {booked} from './payments';
function paymentKey(line:string,part?:number){return part===undefined?`payment:${line}`:`payment:${line}:part:${part}`;}
function isPaymentForLine(key:string,line:string){const prefix=`payment:${line}`;if(key===prefix)return true;if(!key.startsWith(`${prefix}:part:`))return false;return /^(0|[1-9]\d*)$/.test(key.slice(`${prefix}:part:`.length));}
function hasBookingForLine(line:string){for(const key of booked.keys())if(isPaymentForLine(key,line))return true;return false;}
export function splitCheckout(line:string,parts:number[]){parts.forEach((cents,i)=>booked.set(paymentKey(line,i),cents));}
export function wholeCheckout(line:string,cents:number){if(hasBookingForLine(line))return {status:'already-booked'};booked.set(paymentKey(line),cents);return {status:'booked'};}
export function reclaimReservation(line:string){return !hasBookingForLine(line);}

